// TH14 synthetic appearance aliases used by this card.
// Native type 5 -> modern 5; native type 18 -> modern 18 (same-number range).
// See transcribe/th14/bullet-types.md; source stays "th14".
const TH14_BALL2: int = 432;     // native type 5
const TH14_BIG_BALL: int = 640;  // native type 18, colors 0-7

// TH14 v1.00b st03bs.ecl.txt::Boss3 (source lines 222-279), nonspell segment.
// Dependency: Boss3_at (281-321) and SHOOT/SHOOT_DATA EX chain; BossItemPhase/EffChargePoint3
// and the Boss()/MainBoss() entries are context only.
// Source t0 = timerReset at line 229; target source t0 sits after the 120-frame opening buffer.
const TIME_LIMIT: int = 2884;    // 120 opening + 2400 source + 360 tail + 4 startup margin
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 2400;
// Boss-shared free global: sign of F0 (+/-1deg rotation) sampled by parent bullet tasks.
const GLOBAL_F0_SIGN: int = 16;

// Parent big balls: source etEx type2 (ANIM a=1) runs the birth animation; the birth stage is
// omitted by policy. Creation speed is the last etSpeed write (0,0), so ANIM's 4*velocity
// retreat is zero and etDist(16) is the whole birth offset. SHOOT_DATA c=1 deletes the parent
// after the split; the target re-creates that with set_life after the split task has fired.
xformdef PARENT_LIFE {
    wait(61);
    set_life(1);
}

// Source 412 moveRand(60,4,0.4) sample recipe, retargeted to moveLimit(0,128,280,96):
// real position clamp x[-140,140] y[80,176]; direction inner region x+/-70, y[104,152].
sub card_arm_next_step() {
    var k: int = self_int(0);
    var speed: fx = 0fx;
    if k < 60 {
        k = k+1;
        set_self_int(0, k);
        speed = 0.4fx*((60-k) as fx)/60fx;
    }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Signed unit random * pi, kept as unwrapped integer BAM as in the source sample.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Boss3_at EX chain on each parent big ball (source 295-313):
//  WAIT 10 -> ANGLE_ACCEL a=50 r=0.035/frame s=F0(+/-1deg/frame) -> SHOOT.
// SHOOT: aim mode 3 (fixed ring), child EX starts at record 10, c=rank paths, d=6 layers,
//        r=-999 keeps parent angle, s=F1 layer offset, m=-999 keeps parent speed, n=3.0.
// SHOOT_DATA: sprite type 5, color $A (wave B3_at argument), c=1 deletes parent.
sub split_common(shape: int, color: int, f1: int) {
    var sign: int = global(GLOBAL_F0_SIGN);
    wait(10);
    set_ang_vel(0, sign*182); // 0.017453 rad/frame = 1deg/frame
    set_accel(0, 0.035fx);
    wait(50);
    set_ang_vel(0, 0);
    set_accel(0, 0fx);
    var rank: int = global(GVAR_RANK);
    var paths: int = 1;
    if rank >= 2 { paths = rank; } // source c: E1 N1 H2 L3
    var pspeed: fx = $self_speed;
    var px: fx = $self_x;
    var py: fx = $self_y;
    var base: int = $self_angle as int;
    var step: int = 65536/paths;
    for q in 0..6 {
        // Layer speeds interpolate from the parent's current speed to 3.0.
        var v: fx = pspeed+(3fx-pspeed)*(q as fx)/5fx;
        var off: int = q*f1;
        for i in 0..paths {
            var aa: int = base+i*step+off;
            var ang: angle = aa as angle;
            // Child record 10 ANIM a=1: position -= 4*velocity at birth.
            var cx: fx = px-4fx*v*cos(ang);
            var cy: fx = py-4fx*v*sin(ang);
            _ = fire(shape, color, cx, cy, v, ang, none, none);
        }
    }
}
async sub split_wave6() { split_common(TH14_BALL2, 6, 364); }  // B3_at(6): child color 6, F1=+2deg
async sub split_wave2() { split_common(TH14_BALL2, 2, 0); }    // B3_at(2): child color 2, F1=0
async sub split_wave4() { split_common(TH14_BALL2, 4, -364); } // B3_at(4): child color 4, F1=-2deg

// One ring wave. Parent: etSprite(18,1), etAim mode3, count n x 1 layer, random base angle
// (%RANDRAD), final etSpeed(0,0), etDist(16).
sub emit6(n: int) {
    var base: int = rand(65536)-32768;
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, base as angle, 0deg);
    sh_speed(0, 0fx, 0fx);
    sh_dist(0, 16fx);
    sh_xform(0, PARENT_LIFE);
    sh_task(0, split_wave6);
    sh_fire(0);
}
sub emit2(n: int) {
    var base: int = rand(65536)-32768;
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, base as angle, 0deg);
    sh_speed(0, 0fx, 0fx);
    sh_dist(0, 16fx);
    sh_xform(0, PARENT_LIFE);
    sh_task(0, split_wave2);
    sh_fire(0);
}
sub emit4(n: int) {
    var base: int = rand(65536)-32768;
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, base as angle, 0deg);
    sh_speed(0, 0fx, 0fx);
    sh_dist(0, 16fx);
    sh_xform(0, PARENT_LIFE);
    sh_task(0, split_wave4);
    sh_fire(0);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source t0 is this entry point (timerReset line 229): the 2400-frame interrupt window
    // already covers the 60-frame reposition and wait(140) below.
    var until: int = $frame+SOURCE_LIMIT;
    // Source 242-248: stop inherited motion, 60-frame QuadOut reposition to (0,128), wait140.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(140);
    // moveRand ownership (source I0/F0/F1 are not read elsewhere in this segment).
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    var rank: int = global(GVAR_RANK);
    var n: int = 15;      // source etCount: E15 N24 H24 L17
    if rank == 1 { n = 24; }
    if rank == 2 { n = 24; }
    if rank == 3 { n = 17; }
    var sign: int = 1;    // source F0 = +0.017453 before the loop
    loop {
        card_wait(60);
        if $frame >= until { break; }
        set_global(GLOBAL_F0_SIGN, sign);
        emit6(n);
        card_wait(30);
        if $frame >= until { break; }
        sign = -sign;     // source flips F0 after the first at() of each cycle
        set_global(GLOBAL_F0_SIGN, sign);
        emit2(n);
        card_wait(30);
        if $frame >= until { break; }
        emit4(n);
        card_wait(30);
        card_move_rand();
        card_wait(70);
    }
    // Source boundary clear: etClear(640) at the timeout exit.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source Boss() setHitbox(48,48): native ordinary circle uses width*0.5
    set_hurtbox(24fx); // source Boss() setHurtbox(48,48)
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 11800, 0, 0, 0, boss_main);
    loop { wait(600); }
}
